return function(ctx,text,default,callback) local f=Instance.new("Frame",ctx.Parent);f.Name="ColorPicker";f.Size=UDim2.new(1,0,0,42);f.BackgroundTransparency=1;local l=Instance.new("TextLabel",f);l.BackgroundTransparency=1;l.Size=UDim2.new(1,-50,1,0);l.Text=text or "Color";l.TextColor3=ctx.Theme:Get("Text");l.Font=Enum.Font.Gotham;l.TextSize=14;l.TextXAlignment=Enum.TextXAlignment.Left;local b=Instance.new("TextButton",f);b.Position=UDim2.new(1,-40,.5,-14);b.Size=UDim2.fromOffset(34,28);b.Text="";b.BackgroundColor3=default or ctx.Theme:Get("Accent");Instance.new("UICorner",b).CornerRadius=UDim.new(0,8);local c=Control.new(f,ctx,default or ctx.Theme:Get("Accent"));ctx.Input:BindPress(b,function() local r,g,bl=b.BackgroundColor3:ToHSV(); local nextColor=Color3.fromHSV((r+.08)%1,g,bl);b.BackgroundColor3=nextColor;c:SetValue(nextColor);if callback then callback(nextColor)end end);return c end
